<script setup>
import { computed,onMounted } from 'vue'
import { useRouter } from 'vue-router'
import AppShell from '@/components/shell/AppShell.vue'
import { useAssessmentStore } from '@/stores/assessmentStore'
const router=useRouter(),store=useAssessmentStore()
const quotaOrder=['weakness','due_review','current_chapter','challenge']
const quotaLabels={weakness:'薄弱点',due_review:'到期复习',current_chapter:'当前章节',challenge:'挑战题'}
const presets={weakness_check:[.5,.2,.2,.1],stage_retest:[.35,.3,.25,.1],review_due:[.25,.5,.15,.1],comprehensive:[.3,.25,.3,.15]}
const estimatedQuotas=computed(()=>{const raw=presets[store.config.goal].map(v=>v*store.config.question_count),values=raw.map(Math.floor);let left=store.config.question_count-values.reduce((a,b)=>a+b,0);[...raw.keys()].sort((a,b)=>(raw[b]-values[b])-(raw[a]-values[a])||a-b).slice(0,left).forEach(i=>values[i]++);return quotaOrder.map((kind,i)=>({kind,label:quotaLabels[kind],count:values[i]}))})
const hasReadiness=computed(()=>store.readiness!==null)
const ready=computed(()=>hasReadiness.value&&store.readiness.max_question_count>=store.config.question_count)
const inventoryInsufficient=computed(()=>hasReadiness.value&&!store.error&&!store.loading&&!ready.value)
const bp=computed(()=>store.blueprint)
const bucketTotal=computed(()=>bp.value.buckets.reduce((sum,bucket)=>sum+(bucket.count||0),0))
const adjustedTotal=computed(()=>bucketTotal.value)
const canGenerateFromBlueprint=computed(()=>bp.value.done&&bp.value.buckets.length>0&&bucketTotal.value>=5)
onMounted(()=>store.loadReadiness().catch(()=>{}))
async function preview(){try{await store.previewBlueprint()}catch{/* 错误已进 store.blueprint.error，UI 提示降级 */}}
async function begin(){await store.create();router.push(`/apply/assessment/sessions/${store.session.session_id}`)}
async function beginFromBlueprint(){if(!canGenerateFromBlueprint.value)return;await store.create();router.push(`/apply/assessment/sessions/${store.session.session_id}`)}
</script>
<template><AppShell><template #topbar-title>智能组卷</template><main class="setup"><button class="back" @click="router.push('/apply')">返回学以致用</button><p class="eyebrow">智能组卷</p><h1>让每一道题都有学习依据</h1><p>AI 只规划组卷蓝图，题目全部来自已审核题库；AI 不可用时会自动切换规则蓝图。</p><p v-if="store.error" class="error" role="alert">智能组卷信息加载失败：{{store.error}}。请重试或返回使用自主考试。</p><p v-else-if="store.loading&&!hasReadiness" class="status" role="status">正在读取题库与学习证据…</p><section v-if="store.readiness" class="evidence"><h2>本次可用依据</h2><div class="metrics"><span>薄弱点 {{store.readiness.evidence.weakness_points}}</span><span>到期复习 {{store.readiness.evidence.due_review_points}}</span><span>当前章节 {{store.readiness.evidence.current_chapter_points}}</span><span>挑战点 {{store.readiness.evidence.challenge_points}}</span><span>正式题 {{store.readiness.available_questions}}</span></div><p>{{store.readiness.evidence.has_history?'系统会按目标分配配额，并在题目不足时留下调剂说明。':'学习数据较少，将优先覆盖当前章节，并随着作答逐步个性化。'}}</p></section><section v-if="store.readiness" class="panel"><label>组卷目标<select v-model="store.config.goal"><option value="weakness_check">薄弱点检测</option><option value="stage_retest">阶段复测</option><option value="review_due">到期复习</option><option value="comprehensive">综合诊断</option></select></label><label>当前章节<select v-model="store.config.current_chapter_id"><option :value="null">由系统按范围覆盖</option><option v-for="chapter in store.readiness.chapters" :key="chapter.id" :value="chapter.id">{{chapter.name}}</option></select></label><label>作答时长<select v-model.number="store.config.duration_minutes"><option v-for="n in [15,30,45,60]" :key="n" :value="n">{{n}} 分钟</option></select></label><label>检测强度<select v-model="store.config.intensity"><option value="foundation">基础确认</option><option value="standard">标准检测</option><option value="advanced">进阶挑战</option></select></label><label>题量<select v-model.number="store.config.question_count"><option v-for="n in [5,10,15,20]" :key="n" :value="n">{{n}} 题</option></select></label><div class="quota-preview" aria-label="预计蓝图构成"><strong>预计蓝图</strong><span v-for="item in estimatedQuotas" :key="item.kind">{{item.label}} {{item.count}} 题</span><small>实际配额会依据可用证据和正式题库存确定性调剂。</small></div><div class="actions"><button class="primary" :disabled="!ready||bp.streaming" @click="preview">{{bp.streaming?'AI 正在规划蓝图…':'AI 规划蓝图（可微调）'}}</button><button class="quick" :disabled="!ready||store.loading||bp.streaming" @click="begin" title="跳过预览直接按规则蓝图组卷">快速模式</button></div><p v-if="inventoryInsufficient" class="error">当前最多可生成 {{store.readiness.max_question_count}} 题，请减少题量或改用其他课程范围。</p></section><section v-if="bp.streaming||bp.meta||bp.buckets.length||bp.error" class="panel blueprint" aria-live="polite"><h2>AI 蓝图预览</h2><p v-if="bp.error" class="error" role="alert">蓝图预览失败：{{bp.error}}。可直接使用上方「快速模式」按规则蓝图组卷。</p><template v-if="bp.meta||bp.buckets.length"><div class="bp-meta"><span>{{bp.meta?.planning_source==='llm'?'AI 个性化蓝图':'规则保障蓝图'}}</span><span>共 {{adjustedTotal}} 题</span><span v-if="bp.streaming" class="streaming">逐桶接收中…</span></div><div class="buckets"><article v-for="(bucket,index) in bp.buckets" :key="index" class="bucket"><header><span class="kind">{{quotaLabels[bucket.quota_kind]||bucket.quota_kind}}</span><span class="kp">{{bucket.knowledge_point_code}}</span></header><p class="reason">{{bucket.reason}}</p><div class="stepper" v-if="bp.done"><button type="button" :disabled="(bucket.count||0)<=1" aria-label="减少一题" @click="store.adjustBucket(index,-1)">−</button><strong>{{bucket.count}}</strong><button type="button" :disabled="bucket.adjust>=2" aria-label="增加一题" @click="store.adjustBucket(index,1)">＋</button><button type="button" class="drop" aria-label="移除该知识点桶" @click="store.removeBucket(index)">不考</button></div><div class="stepper" v-else><strong>{{bucket.count}}</strong><small>规划中</small></div></article></div><div v-if="bp.done" class="bp-actions"><button class="primary" :disabled="!canGenerateFromBlueprint||store.loading" @click="beginFromBlueprint">按此蓝图生成试卷</button><button class="quick" :disabled="bp.streaming" @click="preview">重新规划</button><p class="hint">已微调 {{adjustedTotal-(bp.meta?.total??adjustedTotal)}} 题 · 每桶可 ±2 题，移除不考的知识点后重新计题量。</p></div></template></section></main></AppShell></template>
<style scoped>.setup{max-width:880px;margin:0 auto;padding:34px 24px 70px}.back{min-height:44px;border:0;background:none;color:var(--accent);padding:0;font:inherit;cursor:pointer}.eyebrow{color:var(--accent)!important;font-weight:600;margin:8px 0 0}h1{margin:4px 0 8px}.setup>p{color:var(--text-secondary)}.status{color:var(--text-secondary)}.evidence,.panel{margin-top:22px;padding:22px;border:1px solid var(--border-subtle);border-radius:var(--radius-lg);background:var(--surface)}h2{font-size:18px;margin-top:0}.metrics{display:flex;flex-wrap:wrap;gap:10px}.metrics span,.quota-preview span{padding:7px 10px;border-radius:var(--radius-pill);background:var(--surface-muted);color:var(--text-secondary)}.evidence p{color:var(--text-secondary)}.panel{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:18px}.panel label{display:flex;flex-direction:column;gap:8px;color:var(--text-secondary)}select{box-sizing:border-box;min-height:44px;padding:0 10px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-primary);font:inherit}.quota-preview{grid-column:1/-1;display:flex;flex-wrap:wrap;align-items:center;gap:8px;padding:16px;border-radius:var(--radius-md);background:var(--surface-muted)}.quota-preview strong,.quota-preview small{flex-basis:100%}.quota-preview small{color:var(--text-secondary)}.actions{grid-column:1/-1;display:flex;gap:12px;flex-wrap:wrap}.actions .primary,.panel>button.primary{min-height:46px;border:0;border-radius:var(--radius-sm);background:var(--accent);color:#fff;font:inherit;cursor:pointer}.actions .quick,.bp-actions .quick{min-height:46px;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-primary);font:inherit;cursor:pointer}.actions button:disabled,.bp-actions button:disabled{opacity:.45;cursor:not-allowed}.panel button:focus-visible,.back:focus-visible,select:focus-visible{outline:2px solid var(--accent);outline-offset:2px}.error{color:var(--danger)!important}.blueprint{grid-template-columns:1fr}.bp-meta{display:flex;flex-wrap:wrap;gap:10px;color:var(--text-secondary)}.bp-meta span{padding:6px 10px;border-radius:var(--radius-pill);background:var(--surface-muted)}.streaming{color:var(--accent)!important;animation:blink 1.2s ease-in-out infinite}@keyframes blink{50%{opacity:.45}}.buckets{display:grid;grid-template-columns:repeat(auto-fill,minmax(240px,1fr));gap:12px;margin-top:14px}.bucket{padding:14px;border:1px solid var(--border-subtle);border-radius:var(--radius-md);background:var(--surface-muted);display:grid;gap:8px}.bucket header{display:flex;justify-content:space-between;align-items:center;gap:8px}.bucket .kind{padding:3px 8px;border-radius:var(--radius-pill);background:var(--accent-soft);color:var(--text-primary);font-size:13px;font-weight:600}.bucket .kp{color:var(--text-tertiary);font-size:13px}.bucket .reason{margin:0;color:var(--text-secondary);font-size:13px}.stepper{display:flex;align-items:center;gap:10px}.stepper strong{font-size:18px;font-variant-numeric:tabular-nums;min-width:24px;text-align:center}.stepper button{min-width:36px;min-height:36px;padding:0;border:1px solid var(--border-subtle);border-radius:var(--radius-sm);background:var(--surface);color:var(--text-primary);cursor:pointer}.stepper button:disabled{opacity:.4;cursor:not-allowed}.stepper .drop{min-width:auto;padding:0 8px;color:var(--danger)}.bp-actions{display:grid;gap:10px;margin-top:16px}.bp-actions .primary{min-height:46px;border:0;border-radius:var(--radius-sm);background:var(--accent);color:#fff;font:inherit;cursor:pointer}.bp-actions .hint{color:var(--text-tertiary);font-size:13px;margin:0}@media(max-width:600px){.setup{padding:24px 16px}.panel{grid-template-columns:1fr}.quota-preview{grid-column:auto}.actions{flex-direction:column}.actions button{width:100%}}</style>
